INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, vertical, ordem, status)
VALUES
 ('cadastros.importar.arquivo','/dashboard/cadastros/importar','Importar cadastros','Subir planilha','Selecione o arquivo .xlsx (ou .csv) que você preencheu a partir da planilha modelo.','O sistema lê as linhas e monta uma prévia antes de gravar — nada entra sem você conferir.','MODELO_importacao_cadastros_PS_clientes.xlsx','Subir um arquivo com cabeçalho diferente do modelo — garanta ao menos as colunas Nome, CPF/CNPJ e mais uma.','gestao_empresarial',10,'publicado'),
 ('cadastros.importar.modo','/dashboard/cadastros/importar','Importar cadastros','Modo de importação','Escolhe o que a importação faz: "Criar e atualizar" (novos entram e os já existentes são atualizados), "Só novos" (ignora quem já existe) ou "Corrigir" (preenche só campos vazios casando por nome, nunca sobrescreve).','Evita duplicar cadastros e dá controle sobre o que é alterado na base atual.','Criar e atualizar','Usar "Corrigir" esperando criar cadastros novos — esse modo só completa quem já existe.','gestao_empresarial',20,'publicado'),
 ('cadastros.importar.so_erros','/dashboard/cadastros/importar','Importar cadastros','Só erros','Marque para ver na prévia apenas as linhas marcadas como erro, filtrando o restante.','Ajuda a revisar e corrigir rapidamente só o que não vai importar.','—','Achar que a linha some da importação ao filtrar — o filtro é só de visualização, não altera o que será gravado.','gestao_empresarial',30,'publicado'),
 ('cadastros.importar.acao_importar','/dashboard/cadastros/importar','Importar cadastros','Importar cadastros','Confirma e grava na base os cadastros marcados como "criar" e "atualizar" na prévia.','Efetiva a importação; reimportar o mesmo arquivo não duplica (casa por CPF/CNPJ).','Importar 42 cadastro(s)','Importar antes de conferir a prévia — as linhas com erro são ignoradas, mas vale revisar os avisos.','gestao_empresarial',40,'publicado'),
 ('cadastros.importar.col_acao','/dashboard/cadastros/importar','Importar cadastros','Ação','O que vai acontecer com a linha: 🟢 criar, 🟡 atualizar, 🔴 erro (fica de fora) ou ⚪ ignorar.','Mostra, linha a linha, o efeito da importação antes de gravar.','🟢 criar','Ignorar as linhas 🔴 erro — elas não entram até o motivo ser corrigido na planilha.','gestao_empresarial',50,'publicado'),
 ('cadastros.importar.col_tipo','/dashboard/cadastros/importar','Importar cadastros','Tipo','Se o cadastro é Cliente, Fornecedor ou ambos, conforme a coluna Tipo da planilha.','Define onde o cadastro aparece no sistema (listas de clientes e/ou fornecedores).','Cliente','Deixar a coluna Tipo em branco quando o cadastro é os dois — informe "Ambos".','gestao_empresarial',60,'publicado'),
 ('cadastros.importar.col_nome','/dashboard/cadastros/importar','Importar cadastros','Nome','O nome fantasia (ou nome) do cadastro, lido da planilha.','Identifica o cadastro na lista e é usado para casar por nome no modo Corrigir.','Padaria Central Ltda','Nomes repetidos na base — no modo Corrigir eles ficam de fora para revisão manual.','gestao_empresarial',70,'publicado'),
 ('cadastros.importar.col_documento','/dashboard/cadastros/importar','Importar cadastros','CPF/CNPJ','O documento do cadastro. É a chave que evita duplicar na reimportação.','Casa o cadastro com um já existente (atualiza em vez de criar) e habilita emissão de nota fiscal.','12.345.678/0001-90','Importar sem CPF/CNPJ — o cadastro entra, mas não poderá emitir nota fiscal até preencher.','gestao_empresarial',80,'publicado'),
 ('cadastros.importar.col_motivo','/dashboard/cadastros/importar','Importar cadastros','Motivo','Quando a ação é erro ou ignorar, explica por quê (documento inválido, duplicado na base, nome repetido…).','Diz exatamente o que corrigir na planilha para a linha passar a importar.','Documento inválido','Reimportar sem corrigir o motivo — a linha continuará como erro.','gestao_empresarial',90,'publicado')
